(function(){
function escapeHtml(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]});}
var CONSENT_TEMPLATES={
  ortho:{label:'Consenso Ortocheratologia',pdf:'Consenso Ortocheratologia.pdf',prefix:'ortho',pages:8,signPage:7,costPage:8},
  lac:{label:'Consenso LAC',pdf:'Consenso lac.pdf',prefix:'lac',pages:5,signPage:4,costPage:5}
};
function cloudConsentEscape(v){return escapeHtml(v===undefined||v===null?'':String(v));}
function cloudConsentOverlay(type,page,d,signature){
  var h='';function f(cls,text,style){if(text)h+='<div class="fill '+cls+'" style="'+style+'">'+cloudConsentEscape(text)+'</div>';}
  if(type==='ortho'&&page===7){f('patient',d.patient,'left:25%;top:42.4%;width:18%');f('date',d.date,'left:49%;top:42.4%;width:15%');if(signature)h+='<img class="sig" src="'+signature+'" style="left:50%;top:47.0%;width:34%;height:3.2%">';f('guardian',d.guardian,'left:10%;top:54.4%;width:77%');f('relationship',d.relationship,'left:25%;top:60.1%;width:40%');}
  if(type==='ortho'&&page===8)f('price',d.orthoPrice?(d.orthoPrice+' euro'):'','left:64%;top:28.0%;width:17%;text-align:center');
  if(type==='lac'&&page===4){f('patient',d.patient,'left:25%;top:54.2%;width:44%');f('date',d.date,'left:75%;top:54.2%;width:16%');if(signature)h+='<img class="sig" src="'+signature+'" style="left:50%;top:56.7%;width:34%;height:3.2%">';f('guardian',d.guardian,'left:10%;top:64.0%;width:77%');f('relationship',d.relationship,'left:25%;top:69.1%;width:40%');}
  if(type==='lac'&&page===5){f('years',d.lacYears,'left:30%;top:21.4%;width:4.2%;text-align:center');f('price',d.lacPrice?(d.lacPrice+' euro'):'','left:65%;top:21.4%;width:18%;text-align:center');f('break',d.lacBreak?(d.lacBreak+' euro'):'','left:65%;top:24.6%;width:18%;text-align:center');f('scratch',d.lacScratch?(d.lacScratch+' euro'):'','left:65%;top:27.6%;width:18%;text-align:center');f('loss',d.lacLoss?(d.lacLoss+' euro'):'','left:65%;top:30.7%;width:18%;text-align:center');f('vyears',d.lacVisitYears,'left:34.2%;top:33.8%;width:3.2%;text-align:center');f('vprice',d.lacVisitPrice?(d.lacVisitPrice+' euro'):'','left:65%;top:33.8%;width:18%;text-align:center');f('cyears',d.lacChangeYears,'left:36.8%;top:36.9%;width:3.2%;text-align:center');f('cprice',d.lacChangePrice?(d.lacChangePrice+' euro'):'','left:65%;top:36.9%;width:18%;text-align:center');}
  return h;
}
var OPTYKER_CONSENT_PAGE_DATA={"ortho-1.png": "data:image/png;base64,", "ortho-2.png": "data:image/png;base64,", "ortho-3.png": "data:image/png;base64,", "ortho-4.png": "data:image/png;base64,", "ortho-5.png": "data:image/png;base64,", "ortho-6.png": "data:image/png;base64,", "ortho-7.png": "data:image/png;base64,", "ortho-8.png": "data:image/png;base64,", "lac-1.png": "data:image/png;base64,", "lac-2.png": "data:image/png;base64,", "lac-3.png": "data:image/png;base64,", "lac-4.png": "data:image/png;base64,", "lac-5.png": "data:image/png;base64,"};
function cloudConsentBuildFromData(type,d,signature,title){
  type=type||((d&&d.type)||'');var t=CONSENT_TEMPLATES[type];if(!t)return '';d=d||{};
  var h='',i,key,src;
  for(i=1;i<=t.pages;i++){
    key=t.prefix+'-'+i+'.png';
    src=(OPTYKER_CONSENT_PAGE_DATA&&OPTYKER_CONSENT_PAGE_DATA[key])||'';
    h+='<div class="page"><img class="bg" src="'+src+'">'+cloudConsentOverlay(type,i,d,signature||'')+'</div>';
  }
  return '<!doctype html><html><head><meta charset="utf-8"><title>'+cloudConsentEscape(title||t.label)+'</title><style>@page{size:A4 portrait;margin:0}*{box-sizing:border-box}html,body{margin:0;padding:0;background:#fff}.page{position:relative;width:210mm;height:297mm;margin:0 auto;overflow:hidden;page-break-after:always;background:#fff}.page:last-child{page-break-after:auto}.bg{position:absolute;left:0;top:0;width:210mm;height:297mm;object-fit:fill}.fill{position:absolute;z-index:2;font-family:"Times New Roman",serif;font-size:11pt;line-height:1.1;background:#fff;padding:1px 3px;min-height:4mm;white-space:nowrap;overflow:hidden}.sig{position:absolute;z-index:3;object-fit:contain;background:transparent}@media screen{body{background:#e8eaed}.page{background:#fff;box-shadow:0 4px 22px rgba(0,0,0,.14);margin:16px auto}}@media print{body{background:#fff}.page{margin:0;box-shadow:none}}</style></head><body>'+h+'</body></html>';
}

var OPTYKER_CONSENT_PDF_DATA={"ortho": "", "lac": ""};
// Shared by Optyker, the customer website and the mobile app.
// Only original blank templates are bundled; customer records come from the existing authenticated APIs.
(function () {
  'use strict';
  const current = document.currentScript;
  const base = new URL('.', current && current.src || location.href);
  let library;
  function pdfLibrary() {
    if (window.PDFLib) return Promise.resolve(window.PDFLib);
    if (!library) library = new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = new URL('vendor/pdf-lib-1.17.1.min.js', base).href;
      script.onload = () => window.PDFLib ? resolve(window.PDFLib) : reject(Error('PDF non disponibile.'));
      script.onerror = () => reject(Error('Impossibile caricare il generatore PDF. Riprova.'));
      document.head.appendChild(script);
    }).catch(error => { library = null; throw error; });
    return library;
  }
  function record(r) {
    const kind = r && (r.kind || r.consent_type);
    if (!['ortho', 'lac'].includes(kind)) throw Error('Tipo di informativa non valido.');
    const form = r.data && r.data.form;
    if (!form || typeof form !== 'object') throw Error('Dati del documento non disponibili. Contatta il negozio.');
    const signature = r.signature_data_url || '';
    if (signature && !/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(signature)) throw Error('Formato della firma non valido.');
    return {kind, form, signature, title:r.file_name || CONSENT_TEMPLATES[kind].label};
  }
  function html(r) {
    const v = record(r);
    return cloudConsentBuildFromData(v.kind, v.form, v.signature, v.title);
  }
  async function pdf(r) {
    const v = record(r);
    const {PDFDocument, StandardFonts, rgb} = await pdfLibrary();
    const doc = await PDFDocument.load(OPTYKER_CONSENT_PDF_DATA[v.kind]);
    // The LAC source also has a completely blank trailing page.
    while (doc.getPageCount() > CONSENT_TEMPLATES[v.kind].pages) doc.removePage(doc.getPageCount() - 1);
    const font = await doc.embedFont(StandardFonts.TimesRoman);
    const sign = v.signature ? await doc.embedPng(v.signature) : null;
    for (const [index, page] of doc.getPages().entries()) {
      const root = document.createElement('div');
      root.innerHTML = cloudConsentOverlay(v.kind, index + 1, v.form, v.signature);
      const {width, height} = page.getSize();
      for (const element of root.children) {
        const style = element.style;
        const x = parseFloat(style.left) / 100 * width;
        const top = parseFloat(style.top) / 100 * height;
        const w = parseFloat(style.width) / 100 * width;
        if (element.classList.contains('sig')) {
          if (!sign) continue;
          const h = parseFloat(style.height) / 100 * height;
          const scale = Math.min(w / sign.width, h / sign.height);
          const sw = sign.width * scale, sh = sign.height * scale;
          page.drawImage(sign, {x:x+(w-sw)/2, y:height-top-(h+sh)/2, width:sw, height:sh});
        } else {
          const text = element.textContent;
          let size = 11;
          const available = Math.max(1, w - 4.5);
          const natural = font.widthOfTextAtSize(text, size);
          if (natural > available) size *= available / natural;
          const h = 13.6;
          page.drawRectangle({x, y:height-top-h, width:w, height:h, color:rgb(1,1,1)});
          const tw = font.widthOfTextAtSize(text, size);
          page.drawText(text, {x:style.textAlign==='center'?x+(w-tw)/2:x+2.25, y:height-top-10.5, size, font, color:rgb(0,0,0)});
        }
      }
    }
    doc.setTitle(v.title);
    return new Blob([await doc.save()], {type:'application/pdf'});
  }
  window.OPTYKER_CONSENT_DOCUMENTS = Object.freeze({html, pdf, version:'20261010-original-pages1'});
})();

})();
